// bench_sim.cpp - SIMULATED benchmark trials for the forensic lab of F12-27.
// No program is timed here: the "times" are numbers generated by a seeded model
// (a base cost, a little noise, and occasional interference from other work on a
// shared machine), in simulated time units. The lab is about how a summary of 20
// trials is chosen, not about any real speed.
#include <algorithm>
#include <cstdint>
#include <iomanip>
#include <iostream>
#include <random>
#include <vector>

std::vector<double> trials(double base, std::mt19937& gen, int n)
{
    auto u = [&gen] { return (static_cast<double>(gen()) + 0.5) / 4294967296.0; };
    std::vector<double> t;
    for (int i = 0; i < n; ++i) {
        double v = base * (0.95 + 0.10 * u());  // +-5 % noise
        if (u() < 0.15) {
            v += 150.0 * u();  // interference from other work, sometimes
        }
        t.push_back(v);
    }
    return t;
}

double median(std::vector<double> v)
{
    std::sort(v.begin(), v.end());
    const std::size_t n = v.size();
    return n % 2 == 1 ? v[n / 2] : (v[n / 2 - 1] + v[n / 2]) / 2.0;
}

int main()
{
    std::mt19937 gen(404);
    const int n = 20;
    const std::vector<double> oldT = trials(100.0, gen, n);
    const std::vector<double> newT = trials(88.0, gen, n);
    std::cout << std::fixed << std::setprecision(1);
    std::cout << "trial   old   new   (simulated time units, not measurements)\n";
    for (int i = 0; i < n; ++i) {
        std::cout << std::setw(5) << i + 1 << std::setw(6) << oldT[static_cast<std::size_t>(i)]
                  << std::setw(6) << newT[static_cast<std::size_t>(i)] << '\n';
    }
    const auto [oMin, oMax] = std::minmax_element(oldT.begin(), oldT.end());
    const auto [nMin, nMax] = std::minmax_element(newT.begin(), newT.end());
    std::cout << std::setprecision(2);
    std::cout << "\nmedian old " << median(oldT) << ", median new " << median(newT)
              << " -> new is " << median(oldT) / median(newT) << "x faster by medians\n";
    std::cout << "best old " << *oMin << ", best new " << *nMin << " -> " << *oMin / *nMin
              << "x by best runs\n";
    std::cout << "worst old " << *oMax << ", best new " << *nMin << " -> " << *oMax / *nMin
              << "x (worst old against best new: a cherry-picked comparison)\n";
    int newWins = 0;
    for (int i = 0; i < n; ++i) {
        newWins += newT[static_cast<std::size_t>(i)] < oldT[static_cast<std::size_t>(i)];
    }
    std::cout << "trials in which new beat old (paired by trial number): " << newWins << " of " << n
              << '\n';
    return 0;
}
